(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1406],{44060:(e,n,t)=>{(window.__NEXT_P=window.__NEXT_P||[]).push(["/businesses/sports-gaming",function(){return t(97601)}])},97601:(e,n,t)=>{"use strict";t.r(n),t.d(n,{__N_SSG:()=>l,default:()=>d});var a=t(37876),o=t(99283);t(14232);let s="/images/businesses/creator-platforms/icons",i="/images/businesses/sports-gaming/carousel",r='export GRID_BASE_URL="https://api.lightspark.com/grid/2025-10-13"\n\n# 1. Create the player customer.\ncurl -X POST "$GRID_BASE_URL/customers" \\\n  -u "$GRID_CLIENT_ID:$GRID_CLIENT_SECRET" \\\n  -H "Content-Type: application/json" \\\n  -d \'{\n    "customerType": "INDIVIDUAL",\n    "platformCustomerId": "player_7b12f9a5",\n    "region": "US",\n    "email": "alex@example.com",\n    "fullName": "Alex Carter",\n    "birthDate": "1995-06-21",\n    "nationality": "US"\n  }\'\n\n# 2. Deposit: a just-in-time quote returns payment instructions\n#    and executes automatically the moment funds arrive.\ncurl -X POST "$GRID_BASE_URL/quotes" \\\n  -u "$GRID_CLIENT_ID:$GRID_CLIENT_SECRET" \\\n  -H "Content-Type: application/json" \\\n  -d \'{\n    "source": { "sourceType": "REALTIME_FUNDING", "customerId": "Customer:abc123", "currency": "USD" },\n    "destination": { "destinationType": "ACCOUNT", "accountId": "InternalAccount:abc123" },\n    "lockedCurrencySide": "SENDING",\n    "lockedCurrencyAmount": 10000\n  }\'\n\n# 3. Payout: quote and execute in one call.\ncurl -X POST "$GRID_BASE_URL/quotes" \\\n  -u "$GRID_CLIENT_ID:$GRID_CLIENT_SECRET" \\\n  -H "Content-Type: application/json" \\\n  -d \'{\n    "source": { "sourceType": "ACCOUNT", "accountId": "InternalAccount:abc123" },\n    "destination": { "destinationType": "ACCOUNT", "accountId": "ExternalAccount:def456" },\n    "lockedCurrencySide": "SENDING",\n    "lockedCurrencyAmount": 250000,\n    "immediatelyExecute": true\n  }\'',c={seo:{title:"Sports & gaming | Lightspark",description:"Instant deposits and payouts for sports and gaming platforms. Bitcoin, stablecoins, and local rails in 65+ countries, on infrastructure with no business hours.",image:{url:"/images/og/businesses/sports-gaming.webp",width:2400,height:1260}},hero:{...{eyebrow:"Business / Sports & gaming",title:"Lightspark for sports & gaming",topRight:"Lightspark API",bottomLeft:"Lightspark API",bottomRight:"(0, 0, 0)",primaryCta:{label:"Book a demo",href:"/contact"},secondaryCta:{label:"View docs",href:"https://docs.lightspark.com/"}},subtitle:(0,a.jsx)(a.Fragment,{children:(0,a.jsx)("p",{children:"Money in before kickoff. Money out at the final whistle. Instant deposits and payouts on rails that work nights and weekends."})})},carouselItems:[{label:"Instant deposits",image:"".concat(i,"/sports-gaming-instant-deposits.webp")},{label:"Player accounts",image:"".concat(i,"/sports-gaming-player-accounts.webp")},{label:"Instant payouts",image:"".concat(i,"/sports-gaming-instant-payouts.webp")},{label:"Global reach",image:"".concat(i,"/sports-gaming-global.webp")},{label:"Stablecoin rails",image:"".concat(i,"/sports-gaming-stablecoins.webp")},{label:"Native Bitcoin",image:"".concat(i,"/sports-gaming-bitcoin.webp")}],tocItems:[{id:"peak-hours",label:"The problem"},{id:"money-in-money-out",label:"The rails"},{id:"winnings-account",label:"The account"},{id:"winnings-economics",label:"The economics"},{id:"not-a-bank",label:"Security & compliance"},{id:"integration",label:"Integration"},{id:"final-whistle",label:"Closing"}],markdown:"# Lightspark for sports & gaming\n\nMoney in before kickoff. Money out at the final whistle. Instant deposits and payouts on rails that work nights and weekends.\n\n### The problem\n\n## Your peak hours are banking's off-hours.\n\nSports and gaming money has a clock on it. The deposit happens minutes before an event. The withdrawal request comes seconds after it ends. Both moments decide whether a player trusts you.\n\nThe banking system was not built for that clock. Card deposits fail at the worst moments, bank transfers take days, and the busiest windows in sports, nights and weekends, are exactly when traditional rails are closed. Every slow payout is a player deciding your product can't be trusted with their money.\n\n### The rails\n\n## Money in before kickoff. Money out at the final whistle.\n\nThe Lightspark API moves money on rails with no business hours. Players deposit in seconds over Bitcoin, stablecoins, and instant local rails, and payouts ride the fastest available rail the moment the result is in. Polymarket runs fast, low-cost Bitcoin deposits on Spark.\n\nYou keep your own wallet and ledger. Lightspark is the money-in and money-out layer underneath it.\n\n### Rail capabilities\n\n- **Instant deposits, before kickoff**: Players fund in seconds over Bitcoin, stablecoins, and instant local rails.\n- **Instant payouts, at the final whistle**: Payouts ride the fastest available local rail, instant where supported.\n- **Always on, nights and weekends**: Instant, 24/7 quotes and transfers out.\n- **Global reach, 65+ countries**: Local rails in and out, so players everywhere fund and cash out in their own currency.\n- **Stablecoin rails, major assets and chains**: USDC, USDT, USDB, and more across supported chains.\n- **Native Bitcoin, built on Spark**: Instant, low-cost transfers on a Lightning-compatible Bitcoin L2.\n\n### The account\n\n## Payouts end at a bank. Or they can start a balance.\n\nInstant rails make you competitive. Where the winnings land can make you sticky. Give players a branded dollar account inside your product: winnings become a balance they can hold, spend with a Visa debit card at 175M+ merchants, or cash out on local rails, without leaving your product.\n\nThe account is optional. The rails work without it. But when winnings stay, the economics change.\n\n### The economics\n\n## Payouts were your biggest cost. Make them your stickiest feature.\n\nWhen winnings sit in a branded account, balances generate reserve rewards, cards generate interchange, FX carries margin, and the next deposit is already funded.\n\n### Revenue streams\n\n- **Reserve rewards**: 2.6-3.0% annualized, $1B in balances = $26M-30M/yr\n- **Card interchange**: ~0.20-1.0%, revenue share on every swipe\n- **FX margin**: 100-200 bps, on local currency conversions\n- **Transaction fees**: Per txn, P2P and merchant payments\n\n### Security & compliance\n\n## Ship the rails. Not the bank behind them.\n\nPlayer money is scrutinized money. Lightspark carries the regulated machinery: money transmission, KYC, sanctions screening, and partner operations, so your team doesn't rebuild it.\n\nIf you add player accounts, they are self-custodial and built on Spark. Neither Lightspark nor the platform can unilaterally move player funds.\n\n### Integration\n\n## One integration. Live in weeks, not years.\n\nYour team starts with one API, a sandbox, and the normal objects you would expect: customers, accounts, quotes, transactions, and webhooks. Create a player, generate deposit instructions with a quote, and run a one-call payout: https://app.lightspark.com/signup\n\nThe docs give your team the implementation path: OpenAPI, copyable examples, sandbox test credentials, Postman collections, and AI-readable pages: https://docs.lightspark.com/\n\n```bash\n".concat(r,"\n```\n\n### Closing\n\n## The game is instant. The money should be too.\n\nPlayers judge you twice: when money goes in, and when it comes out. Win both moments and the deposit stops being friction, the payout stops being a support ticket, and the account becomes the reason they stay.\n\nYour brand. Your economics. One integration.\n\nBook a demo: /contact\nView docs: https://docs.lightspark.com/\n"),sections:[{kind:"prose",id:"peak-hours",eyebrow:"The problem",eyebrowMobileOnly:!0,h2:{primary:"Your peak hours",secondary:"are banking’s off-hours."},body:["Sports and gaming money has a clock on it. The deposit happens minutes before an event. The withdrawal request comes seconds after it ends. Both moments decide whether a player trusts you.","The banking system was not built for that clock. Card deposits fail at the worst moments, bank transfers take days, and the busiest windows in sports, nights and weekends, are exactly when traditional rails are closed. Every slow payout is a player deciding your product can’t be trusted with their money."]},{kind:"accordion",id:"money-in-money-out",eyebrow:"The rails",h2:{primary:"Money in before kickoff.",secondary:"Money out at the final whistle."},body:["The Lightspark API moves money on rails with no business hours. Players deposit in seconds over Bitcoin, stablecoins, and instant local rails, and payouts ride the fastest available rail the moment the result is in. Polymarket runs fast, low-cost Bitcoin deposits on Spark.","You keep your own wallet and ledger. Lightspark is the money-in and money-out layer underneath it."],items:[{title:"Instant deposits",meta:"Before kickoff",text:"Players fund in seconds over Bitcoin, stablecoins, and instant local rails. Polymarket runs fast, low-cost Bitcoin deposits on Spark.",icon:"".concat(s,"/IconDollar.svg")},{title:"Instant payouts",meta:"At the final whistle",text:"Payouts ride the fastest available local rail, instant where supported, the moment the result is in. No cutoff to explain to a winner.",icon:"".concat(s,"/IconBank.svg")},{title:"Always on",meta:"Nights and weekends",text:"Balances support instant, 24/7 quotes and transfers out. The rails work when your traffic peaks, not when banks are open.",icon:"".concat(s,"/IconClock.svg")},{title:"Global reach",meta:"65+ countries",text:"Local rails in and out across PIX, UPI, SEPA, FPS, and more, so players everywhere fund and cash out in their own currency.",icon:"".concat(s,"/IconGlobe.svg")},{title:"Stablecoin rails",meta:"Major assets and chains",text:"Accept and deliver USDC, USDT, USDB, and other supported stablecoins across Base, Solana, Ethereum, Spark, Arbitrum, Tron, and more.",icon:"".concat(s,"/IconUSDC.svg")},{title:"Native Bitcoin",meta:"Built on Spark",text:"Bitcoin is a first-class rail: instant, low-cost transfers on Spark, a Lightning-compatible Bitcoin L2.",icon:"".concat(s,"/IconBitcoinLogo.svg")}]},{kind:"prose",id:"winnings-account",eyebrow:"The account",h2:{primary:"Payouts end at a bank.",secondary:"Or they can start a balance."},body:["Instant rails make you competitive. Where the winnings land can make you sticky. Give players a branded dollar account inside your product: winnings become a balance they can hold, spend with a Visa debit card at 175M+ merchants, or cash out on local rails, without leaving your product.","The account is optional. The rails work without it. But when winnings stay, the economics change."]},{kind:"revenue",id:"winnings-economics",eyebrow:"The economics",h2:{primary:"Payouts were your biggest cost.",secondary:"Make them your stickiest feature."},body:["Most platforms treat the payout as the end of the relationship: a fee, a handoff, and a balance that now lives somewhere else. Winnings that leave instantly build trust. Winnings that land in an account worth keeping build a business.","When winnings sit in a branded account, balances generate reserve rewards, cards generate interchange, FX carries margin, and the next deposit is already funded. Every reason a player keeps money with you is a reason they play again."],items:[{title:"Reserve rewards",stat:"2.6-3.0% annualized",text:"$1B in balances = $26M-30M/yr",color:"#11a967"},{title:"Card interchange",stat:"~0.20-1.0%",text:"revenue share on every swipe",color:"#118453"},{title:"FX margin",stat:"100-200 bps",text:"on local currency conversions",color:"#00b3e0"},{title:"Transaction fees",stat:"Per txn",text:"P2P and merchant payments",color:"#0072db"}],caption:"Program economics depend on balances, card usage, FX volume, and enabled rails."},{kind:"accordion",id:"not-a-bank",eyebrow:"Security & compliance",h2:{primary:"Ship the rails.",secondary:"Not the bank behind them."},body:["Player money is scrutinized money. Moving it used to mean building the regulated machinery yourself: money transmission, KYC, sanctions screening, dispute handling, and partner operations. Lightspark carries that side of the equation so your team doesn’t have to.","If you add player accounts, they are self-custodial and built on Spark. Neither Lightspark nor the platform can unilaterally move player funds. Boundaries enforced by architecture instead of trust."],items:[{title:"Regulated rails",meta:"Licenses and partners",text:"Lightspark Payments is registered with FinCEN as a money services business and holds money transmission licenses or registrations where required for Grid Transaction Services, with banking and payment partners behind the regulated rails.",icon:"".concat(s,"/IconLaw.svg")},{title:"Compliance operations",meta:"KYC, KYB, sanctions",text:"Lightspark handles the operational work platforms do not want to rebuild: identity checks, business verification, sanctions screening, risk review, and the compliance requirements attached to supported corridors.",icon:"".concat(s,"/IconUserAdded.svg")},{title:"Security program",meta:"SOC 2 Type II and NIST CSF",text:"The infrastructure is backed by Lightspark’s security program, audited under SOC 2 Type II with NIST CSF–aligned controls, so teams can evaluate it like enterprise financial infrastructure.",icon:"".concat(s,"/IconShieldCheck.svg")},{title:"Audit trail",meta:"Traceable movement",text:"Standard API objects and webhooks keep funding, withdrawals, card activity, quotes, and settlement status visible to your team instead of hiding money movement in a black box.",icon:"".concat(s,"/IconSquareChecklistMagnifyingGlass.svg")},{title:"Player authorization",meta:"Customer signed",text:"With player accounts, outbound movement requires the player to authorize from their device. You design the flow, limits, and approvals, but the account owner stays in the loop when funds leave.",icon:"".concat(s,"/IconPageTextLock.svg")},{title:"Self-custody on Spark",meta:"No unilateral movement",text:"Player accounts are built on Spark wallets, so account control is enforced at the wallet layer. Neither Lightspark nor the platform can unilaterally move player funds.",icon:"".concat(s,"/IconUserKey.svg")},{title:"Platform controls",meta:"Your product surface",text:"You own the brand, UX, account rules, approval flows, and user experience. Lightspark powers the rails and regulated movement underneath.",icon:"".concat(s,"/IconSettingsKnob.svg")}]},{kind:"integration",id:"integration",eyebrow:"Integration",h2:{primary:"One integration.",secondary:"Live in weeks, not years."},body:[(0,a.jsxs)(a.Fragment,{children:["This is not a multi-year banking build. Your team starts with one API, a sandbox, and the normal objects you would expect: customers, accounts, quotes, transactions, and webhooks. Create a player, generate deposit instructions with a quote, and run a one-call payout in ",(0,a.jsx)("a",{href:"https://app.lightspark.com/signup",children:"sandbox"})," before production money moves."]}),(0,a.jsxs)(a.Fragment,{children:["The hard parts are already packaged: deposit instructions, instant rails, webhook events, and compliance operations. The"," ",(0,a.jsx)("a",{href:"https://docs.lightspark.com/",children:"docs"})," give your team the implementation path: OpenAPI, copyable examples, sandbox test credentials, Postman collections, and AI-readable pages."]})],snippet:{code:r,caption:"The happy path: create a player, generate deposit instructions, and run a one-call instant payout."}},{kind:"closing",id:"final-whistle",eyebrow:"Closing",h2:{primary:"The game is instant.",secondary:"The money should be too."},body:["Players judge you twice: when money goes in, and when it comes out. Win both moments and the deposit stops being friction, the payout stops being a support ticket, and the account becomes the reason they stay.","Your brand. Your economics. One integration."],primaryCta:{label:"Book a demo",href:"/contact"},secondaryCta:{label:"View docs",href:"https://docs.lightspark.com/"}}]};var l=!0;function d(e){let{preview:n,layout:t}=e;return(0,a.jsx)(o.w,{content:c,layout:t,preview:n})}}},e=>{e.O(0,[1440,3136,6021,73,7022,4560,1654,636,6593,8792],()=>e(e.s=44060)),_N_E=e.O()}]);